try:
    print('>>> f = divmod')
    print('>>> x = b""')
    print('>>> y = slice(0)')
    print('>>> f(x, y)')
    f = divmod
    x = b""
    y = slice(0)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
